# Add the missing vertically reflected cell-patterns in the three inferred row-pairs.
starts=[0,6,12,18]; cols=[0,6,12,18]
for sr, tr, c in [(0,1,1),(2,1,3),(2,3,0),(2,3,1)]:
    for rr in range(5):
        for cc in range(5):
            v=grid[starts[sr]+(4-rr)][cols[c]+cc]
            if v not in (0,):
                assert grid[starts[tr]+rr][cols[c]+cc] in (0,v), (sr,tr,c,rr,cc)
                grid[starts[tr]+rr][cols[c]+cc]=v
print('\n'.join(' '.join(map(str,r)) for r in grid))
